Likutay Halachos – Choshen Mishpat II – Matanah u'Matanas Sh'chiv Mayra 5 (Rashay Prakim)

@import url('https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&display=swap');

:root { --bg:#faf8f4; --text:#2b2420; --accent:#8b6914; --accent-dark:#6b4f0e; --border:#d4c4a0; --highlight:#f5ecd7; --verse-bg:#f0e8d4; --section-num:#a0842a; --summary-bg:#eef6ee; --summary-border:#7aab7a; --key-term:#5a3e1b; }

* { margin:0; padding:0; box-sizing:border-box; }

body { font-family:'EB Garamond',Georgia,'Times New Roman',serif; font-size:18px; line-height:1.85; color:var(--text); background-color:var(--bg); max-width:780px; margin:0 auto; padding:40px 30px 80px; text-align:justify; }

.main-title { text-align:center; font-size:28px; font-weight:700; color:var(--accent-dark); margin-bottom:6px; letter-spacing:0.5px; }

.sub-title { text-align:center; font-size:22px; font-weight:600; color:var(--accent); margin-bottom:30px; }

.halacha-intro { background-color:var(--verse-bg); border-left:4px solid var(--accent); padding:16px 22px; margin:24px 0; font-size:17px; line-height:1.75; border-radius:0 6px 6px 0; }

.section-break { text-align:center; font-size:14px; color:#aaa; margin:28px 0 12px; letter-spacing:3px; }

.paragraph { margin-bottom:18px; text-indent:2em; }

.verse { color:var(--accent-dark); font-style:italic; font-weight:500; }

.verse-source { font-size:14px; color:#888; font-style:normal; font-weight:400; }

.key-term { font-style:italic; color:var(--key-term); font-weight:500; }

.definition { font-size:15px; color:#666; }

.talmudic-quote { display:block; background-color:var(--verse-bg); border-left:3px solid var(--border); padding:10px 18px; margin:14px 0; font-style:italic; font-size:17px; border-radius:0 4px 4px 0; }

.precisely { font-weight:600; color:var(--accent-dark); }

.closing { text-align:center; font-size:17px; font-style:italic; color:var(--accent); margin:30px 0; letter-spacing:0.5px; }

.summary-box { background-color:var(--summary-bg); border:2px solid var(--summary-border); border-radius:8px; padding:22px 26px; margin:40px 0 20px; }

.summary-box h3 { font-size:18px; color:#3a6b3a; margin-bottom:12px; text-align:center; letter-spacing:0.5px; }

.summary-box p { font-size:16px; line-height:1.7; margin-bottom:10px; text-indent:0; text-align:justify; }

@media (max-width:600px) { body { font-size:16px; padding:20px 16px 60px; } .main-title { font-size:22px; } .sub-title { font-size:18px; } }

